def ca_rule_90(grid, seeds, nsteps, H=None, W=None, mirror=False):
    H_=len(grid); W_=len(grid[0])
    g=[r[:] for r in grid]
    for _ in range(nsteps):
        new=[[0]*W_ for _ in range(H_)]
        for i in range(H_):
            for j in range(W_):
                a=g[max(0,i-1) if False else i-1 ][j] if 0<i<H_-1 else 0
                b=g[min(H_-1,i+1) if False else i+1 ][j] if 0<i<H_-1 else 0
                c=g[i][max(0,j-1) if False else j-1] if 0<j<W_-1 else 0
                d=g[i][min(W_-1,j+1) if False else j+1] if 0<j<W_-1 else 0
                new[i][j]= (a+b+c+d)%2
        g=new
    return g

def gen_r90(seeds,H,W,n):
    g=[[0]*W for _ in range(H)]
    for r_,c_ in seeds: g[r_][c_]=1
    for _ in range(n):
        ng=[[0]*W for _ in range(H)]
        for i in range(H):
            for j in range(W):
                u,d = g[max(0,i-1)][j], g[min(H-1,i+1)][j] if i+1<H else 0
                l,r = g[i][max(0,j-1)], g[i][min(W-1,j+1)] if j+1<W else 0
                ng[i][j]=(u+d+l+r)%2
        g=ng
    return g

